static pg_agent agent;
static pg_journal journal={.file=-1,.directory=-1};
static unsigned starts;
static int error_mode,sync_fail,crash_sync;
int __real_fsync(int);
int __wrap_fsync(int fd){if(crash_sync)_exit(73);if(sync_fail){sync_fail=0;errno=EIO;return -1;}return __real_fsync(fd);}
static int start(void *ctx,const pg_session *s){(void)ctx;(void)s;++starts;return 0;}
static int next(void *ctx,pg_model_event *event){(void)ctx;*event=(pg_model_event){.kind=error_mode?PG_MODEL_ERROR:PG_MODEL_DONE};return 0;}
static void close_model(void *ctx){(void)ctx;}
static pg_slice slice(const char *s){return (pg_slice){s,strlen(s)};}
static void fresh(void){assert(!pg_agent_init(&agent,(pg_model){0,start,next,close_model,close_model},(pg_tools){0}));journal=(pg_journal){.file=-1,.directory=-1};sync_fail=crash_sync=0;}
static void finish(pg_outcome outcome){pg_client client=pg_agent_client(&agent);unsigned terminal=0;for(unsigned i=0;i<12;++i){pg_event event;if(client.poll(client.context,&event)&&event.kind==PG_RUN_FINISHED){assert(event.outcome==outcome);terminal=1;break;}}assert(terminal);}
