static pg_store_result store_spy(void *ctx,const pg_session_change *change,uint64_t expected,uint64_t *seq){assert(ctx==&store_mode);++store_calls;assert(change->kind==PG_SESSION_SUBMISSION&&change->count==1&&change->text.data!=borrowed_key&&change->messages[0].text!=borrowed_text);assert(!agent.commits.submission_count&&!agent.session.count&&!agent.commits.run.id);pg_submissions service=pg_agent_submissions(&agent);pg_submission_record out;assert(service.find(service.context,slice("borrowed"),&out)==1);assert(service.submit(service.context,slice("reentry"),slice("x"),&out));borrowed_key[0]='X';borrowed_text[0]='Y';*seq=expected+1;return store_mode==1?PG_STORE_REJECTED:store_mode==2?PG_STORE_UNCERTAIN:PG_STORE_OK;}
static void acknowledgement(void){for(store_mode=0;store_mode<3;++store_mode){fresh();strcpy(borrowed_key,"borrowed");strcpy(borrowed_text,"original");store_calls=0;assert(!pg_agent_bind_storage(&agent,(pg_storage){&store_mode,store_spy}));pg_submissions s=pg_agent_submissions(&agent);pg_submission_record out,saved;memset(&out,0xa7,sizeof(out));saved=out;int rc=s.submit(s.context,slice(borrowed_key),slice(borrowed_text),&out);assert(store_calls==1);if(!store_mode){assert(!rc&&agent.commits.submission_count==1&&!strcmp(out.request_id,"borrowed")&&!strcmp(agent.session.messages[0].text,"original"));duplicate(s,"borrowed",out.id,0);}else{assert(rc&&!agent.commits.submission_count&&!agent.session.count&&!memcmp(&out,&saved,sizeof(out)));assert(agent.commits.failed==(unsigned)(store_mode==2));}}}
static uint32_t u32(const unsigned char *p){return (uint32_t)p[0]|(uint32_t)p[1]<<8|(uint32_t)p[2]<<16|(uint32_t)p[3]<<24;}
static uint64_t hash(const unsigned char *p,size_t n){uint64_t h=UINT64_C(0xcbf29ce484222325);for(size_t i=0;i<n;++i)h=(h^p[i])*UINT64_C(0x100000001b3);return h;}
static void rehash(unsigned char *p,size_t n){uint64_t h=hash(p,32);memcpy(p+32,&h,8);h=hash(p,n-16);memcpy(p+n-16,&h,8);}
static void write_file(int root,const char *name,const unsigned char *p,size_t n){int fd=openat(root,name,O_WRONLY|O_CREAT|O_TRUNC,0600);assert(fd>=0&&write(fd,p,n)==(ssize_t)n&&!close(fd));}
static void open_file(int root,const char *name){fresh();assert(!pg_journal_open(&journal,root,name,&agent.session,&agent.commits));}
